package com.godjiismp.weapons;
import com.godjiismp.skills.Skills;import net.minecraft.ChatFormatting;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.InteractionHand;import net.minecraft.world.InteractionResultHolder;import net.minecraft.world.entity.EquipmentSlot;import net.minecraft.world.entity.LivingEntity;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.Item;import net.minecraft.world.item.ItemStack;import net.minecraft.world.item.Items;import net.minecraft.world.level.Level;
public final class LegendaryWeapon extends Item {private final int index;public LegendaryWeapon(int index,Properties props){super(props);this.index=index;}public int index(){return index;}@Override public int getEnchantmentValue(){return WeaponsConfig.enchantability[index];}@Override public boolean isValidRepairItem(ItemStack stack,ItemStack repair){return repair.is(Items.NETHERITE_BLOCK);}@Override public boolean hurtEnemy(ItemStack stack,LivingEntity target,LivingEntity attacker){if(!attacker.level().isClientSide)stack.hurtAndBreak(1,attacker,EquipmentSlot.MAINHAND);return true;}@Override public InteractionResultHolder<ItemStack> use(Level level,Player player,InteractionHand hand){ItemStack stack=player.getItemInHand(hand);if(level.isClientSide)return InteractionResultHolder.success(stack);if(!(player instanceof ServerPlayer sp))return InteractionResultHolder.pass(stack);int req=WeaponsConfig.requiredAttack[index];if(req>0&&Skills.level(sp,0)<req){sp.sendSystemMessage(Component.literal("Requires Attack Lv"+req).withStyle(ChatFormatting.RED));return InteractionResultHolder.fail(stack);}if(index==0||index==2){if(sp.getCooldowns().isOnCooldown(this))return InteractionResultHolder.fail(stack);if(index==0)WeaponAbilities.boneWave(sp);else WeaponAbilities.groundSlam(sp);sp.getCooldowns().addCooldown(this,WeaponsConfig.cooldownSeconds[index]*20);return InteractionResultHolder.consume(stack);}return InteractionResultHolder.pass(stack);}}
